/**
 * <div id="class.mysql-xdevapi-baseresult" class="reference"> <h1 class="title">BaseResult interface</h1>  <div class="partintro"><p class="verinfo">(PECL mysql-xdevapi &gt;= 8.0.11)</p>  <div class="section" id="mysql-xdevapi-baseresult.intro">   <h2 class="title">简介</h2>   <p class="para">   </p>  </div>  <div class="section" id="mysql-xdevapi-baseresult.synopsis">   <h2 class="title">类摘要</h2>   <div class="classsynopsis">    <span class="ooclass"><strong class="classname"></strong></span>    <div class="classsynopsisinfo">     <span class="ooclass">      <span class="modifier">class</span> <strong class="classname">mysql_xdevapi\BaseResult</strong>     </span>     {</div>        <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>getWarnings</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>getWarningsCount</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div>   }</div>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link BaseResult::getWarnings} — Fetch warnings from last operation</li><li>{@link BaseResult::getWarningsCount} — Fetch warning count from last operation</li></ul></div>
 * 
 * Interface BaseResult
 * @package mysql_xdevapi
 */
interface BaseResult
{
    /**
 * <div id="mysql-xdevapi-baseresult.getwarnings" class="refentry"> <div class="refnamediv">  <h1 class="refname">BaseResult::getWarnings</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">BaseResult::getWarnings</span> — <span class="dc-title">Fetch warnings from last operation</span></p> </div> <div class="refsect1 description" id="refsect1-mysql-xdevapi-baseresult.getwarnings-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\BaseResult::getWarnings</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div>  <p class="para rdfs-comment">   Fetches warnings generated by MySQL server's last operation.  </p> </div> <div class="refsect1 parameters" id="refsect1-mysql-xdevapi-baseresult.getwarnings-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mysql-xdevapi-baseresult.getwarnings-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   An array of Warning objects from the last operation. Each object   defines an error 'message', error 'level', and error 'code'. An empty   array is returned if no errors are present.  </p> </div> <div class="refsect1 examples" id="refsect1-mysql-xdevapi-baseresult.getwarnings-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">mysql_xdevapi\RowResult::getWarnings()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$session </span><span style="color: #007700">= </span><span style="color: #9876AA">mysql_xdevapi\getSession</span><span style="color: #007700">(</span><span style="color: #DD0000">"mysqlx://user:password@localhost"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"CREATE DATABASE foo"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"CREATE TABLE foo.test_table(x int)"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$schema </span><span style="color: #007700">= </span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getSchema</span><span style="color: #007700">(</span><span style="color: #DD0000">"foo"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$table  </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getTable</span><span style="color: #007700">(</span><span style="color: #DD0000">"test_table"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$table</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'x'</span><span style="color: #007700">])-&gt;</span><span style="color: #9876AA">values</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">])-&gt;</span><span style="color: #9876AA">values</span><span style="color: #007700">([</span><span style="color: #9876AA">2</span><span style="color: #007700">])-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$res </span><span style="color: #007700">= </span><span style="color: #9876AA">\$table</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">select</span><span style="color: #007700">([</span><span style="color: #DD0000">'x/0 as bad_x'</span><span style="color: #007700">])-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$warnings </span><span style="color: #007700">= </span><span style="color: #9876AA">\$res</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getWarnings</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$warnings</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Array<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;mysql_xdevapi\Warning&nbsp;Object<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[message]&nbsp;=&gt;&nbsp;Division&nbsp;by&nbsp;0<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[level]&nbsp;=&gt;&nbsp;2<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[code]&nbsp;=&gt;&nbsp;1365<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;)<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;mysql_xdevapi\Warning&nbsp;Object<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[message]&nbsp;=&gt;&nbsp;Division&nbsp;by&nbsp;0<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[level]&nbsp;=&gt;&nbsp;2<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[code]&nbsp;=&gt;&nbsp;1365<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;)<br>)</blockquote></div>   </div>  </div> </div></div>
 * 
     * Fetch warnings from last operation
     * @link https://www.php.net/manual/en/mysql-xdevapi-baseresult.getwarnings.php
     * @return array
     */
    public function getWarnings(): array;

    /**
 * <div id="mysql-xdevapi-baseresult.getwarningscount" class="refentry"> <div class="refnamediv">  <h1 class="refname">BaseResult::getWarningsCount</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">BaseResult::getWarningsCount</span> — <span class="dc-title">Fetch warning count from last operation</span></p> </div> <div class="refsect1 description" id="refsect1-mysql-xdevapi-baseresult.getwarningscount-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\BaseResult::getWarningsCount</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div>  <p class="para rdfs-comment">   Returns the number of warnings raised by the last operation. Specifically,    these warnings are raised by the MySQL server.  </p> </div> <div class="refsect1 parameters" id="refsect1-mysql-xdevapi-baseresult.getwarningscount-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mysql-xdevapi-baseresult.getwarningscount-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   The number of warnings from the last operation.  </p> </div> <div class="refsect1 examples" id="refsect1-mysql-xdevapi-baseresult.getwarningscount-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">mysql_xdevapi\RowResult::getWarningsCount()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$session </span><span style="color: #007700">= </span><span style="color: #9876AA">mysql_xdevapi\getSession</span><span style="color: #007700">(</span><span style="color: #DD0000">"mysqlx://user:password@localhost"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"DROP DATABASE IF EXISTS foo"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"CREATE DATABASE foo"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"CREATE TABLE foo.test_table(x int)"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$schema </span><span style="color: #007700">= </span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getSchema</span><span style="color: #007700">(</span><span style="color: #DD0000">"foo"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$table  </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getTable</span><span style="color: #007700">(</span><span style="color: #DD0000">"test_table"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$table</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'x'</span><span style="color: #007700">])-&gt;</span><span style="color: #9876AA">values</span><span style="color: #007700">([</span><span style="color: #9876AA">1</span><span style="color: #007700">])-&gt;</span><span style="color: #9876AA">values</span><span style="color: #007700">([</span><span style="color: #9876AA">2</span><span style="color: #007700">])-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$res </span><span style="color: #007700">= </span><span style="color: #9876AA">\$table</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">select</span><span style="color: #007700">([</span><span style="color: #DD0000">'x/0 as bad_x'</span><span style="color: #007700">])-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br>echo </span><span style="color: #9876AA">\$res</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getWarningsCount</span><span style="color: #007700">();<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">2</blockquote></div>   </div>  </div> </div></div>
