/**
 * <div id="class.mysql-xdevapi-collection" class="reference"> <h1 class="title">Collection class</h1>  <div class="partintro"><p class="verinfo">(PECL mysql-xdevapi &gt;= 8.0.11)</p>  <div class="section" id="mysql-xdevapi-collection.intro">   <h2 class="title">简介</h2>   <p class="para">   </p>  </div>  <div class="section" id="mysql-xdevapi-collection.synopsis">   <h2 class="title">类摘要</h2>   <div class="classsynopsis">    <span class="ooclass"><strong class="classname"></strong></span>    <div class="classsynopsisinfo">     <span class="ooclass">      <span class="modifier">class</span> <strong class="classname">mysql_xdevapi\Collection</strong>     </span>          <span class="oointerface"><span class="modifier">implements</span>        <a href="https://php.net/manual/zh/class.mysql-xdevapi-schemaobject.php" class="interfacename">mysql_xdevapi\SchemaObject</a></span> {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 属性 </div>    <div class="fieldsynopsis">     <span class="modifier">public</span>      <var class="varname"><a href="https://php.net/manual/zh/class.mysql-xdevapi-collection.php#mysql-xdevapi-collection.props.name">\$<var class="varname">name</var></a></var>;</div>        <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>add</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$document</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mysql-xdevapi-collectionadd.php" class="type mysql_xdevapi\CollectionAdd" style="color:#EAB766">mysql_xdevapi\CollectionAdd</a></span></div><div class="methodsy