 class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>dropIndex</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$index_name</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>existsInDatabase</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>find</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$search_condition</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mysql-xdevapi-collectionfind.php" class="type mysql_xdevapi\CollectionFind" style="color:#EAB766">mysql_xdevapi\CollectionFind</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>getName</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>getOne</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$id</span></span>): <span class="type" style="color:#EAB766">Document</span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>getSchema</strong></span>(): <span class="type" style="color:#EAB766">Schema Object</span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>getSession</strong></span>(): <span class="type" style="color:#EAB766">Session</span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>modify</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$search_condition</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mysql-xdevapi-collectionmodify.php" class="type mysql_xdevapi\CollectionModify" style="color:#EAB766">mysql_xdevapi\CollectionModify</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>remove</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$search_condition</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mysql-xdevapi-collectionremove.php" class="type mysql_xdevapi\CollectionRemove" style="color:#EAB766">mysql_xdevapi\CollectionRemove</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>removeOne</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$id</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mysql-xdevapi-result.php" class="type mysql_xdevapi\Result" style="color:#EAB766">mysql_xdevapi\Result</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>replaceOne</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$id</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$doc</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mysql-xdevapi-result.php" class="type mysql_xdevapi\Result" style="color:#EAB766">mysql_xdevapi\Result</a></span></div>   }</div>  </div>    <div class="section" id="mysql-xdevapi-collection.props">   <h2 class="title">属性</h2>   <dl>         <dt id="mysql-xdevapi-collection.props.name"><var class="varname">name</var></dt>     <dd>      <p class="para"></p>     </dd>       </dl>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link Collection::add} — Add collection document</li><li>{@link Collection::addOrReplaceOne} — Add or replace collection document</li><li>{@link Collection::__construct} — Collection constructor</li><li>{@link Collection::count} — Get document count</li><li>{@link Collection::createIndex} — Create collection index</li><li>{@link Collection::dropIndex} — Drop collection index</li><li>{@link Collection::existsInDatabase} — Check if collection exists in database</li><li>{@link Collection::find} — Search for document</li><li>{@link Collection::getName} — Get collection name</li><li>{@link Collection::getOne} — Get one document</li><li>{@link Collection::getSchema} — Get schema object</li><li>{@link Collection::getSession} — Get session object</li><li>{@link Collection::modify} — Modify collection documents</li><li>{@link Collection::remove} — Remove collection documents</li><li>{@link Collection::removeOne} — Remove one collection document</li><li>{@link Collection::replaceOne} — Replace one collection document</li></ul></div>
 * 
 * Class Collection
 * @link https://www.php.net/manual/en/class.mysql-xdevapi-collection.php
 * @package mysql_xdevapi
 */
class Collection
{
    /**
 * <div id="mysql-xdevapi-collection.construct" class="refentry"> <div class="refnamediv">  <h1 class="refname">Collection::__construct</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">Collection::__construct</span> — <span class="dc-title">Collection constructor</span></p> </div> <div class="refsect1 description" id="refsect1-mysql-xdevapi-collection.construct-description">  <h3 class="title">说明</h3>  <div class="constructorsynopsis dc-description">   <span class="modifier">private</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\Collection::__construct</strong></span>()</div>  <p class="para rdfs-comment">   Construct a Collection object.  </p> </div> <div class="refsect1 parameters" id="refsect1-mysql-xdevapi-collection.construct-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 examples" id="refsect1-mysql-xdevapi-collection.construct-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">mysql_xdevapi\Collection::getOne()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$session </span><span style="color: #007700">= </span><span style="color: #9876AA">mysql_xdevapi\getSession</span><span style="color: #007700">(</span><span style="color: #DD0000">"mysqlx://user:password@localhost"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"DROP DATABASE IF EXISTS addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"CREATE DATABASE addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$schema     </span><span style="color: #007700">= </span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getSchema</span><span style="color: #007700">(</span><span style="color: #DD0000">"addressbook"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$collection </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #DD0000">'{"name": "Alfred", "age": 42, "job": "Butler"}'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #FF8000">// A unique _id is (by default, and recommended) generated by MySQL Server<br>// This retrieves the generated _id's; only one in this example, so \$ids[0]<br></span><span style="color: #9876AA">\$ids        </span><span style="color: #007700">= </span><span style="color: #9876AA">\$result</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getGeneratedIds</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$alfreds_id </span><span style="color: #007700">= </span><span style="color: #9876AA">\$ids</span><span style="color: #007700">[</span><span style="color: #9876AA">0</span><span style="color: #007700">];<br><br></span><span style="color: #FF8000">// ...<br><br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$alfreds_id</span><span style="color: #007700">);<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getOne</span><span style="color: #007700">(</span><span style="color: #9876AA">\$alfreds_id</span><span style="color: #007700">));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">00005b6b536100000000000000b1<br><br>Array<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[_id]&nbsp;=&gt;&nbsp;00005b6b536100000000000000b1<br>&nbsp;&nbsp;&nbsp;&nbsp;[age]&nbsp;=&gt;&nbsp;42<br>&nbsp;&nbsp;&nbsp;&nbsp;[job]&nbsp;=&gt;&nbsp;Butler<br>&nbsp;&nbsp;&nbsp;&nbsp;[name]&nbsp;=&gt;&nbsp;Alfred<br>)</blockquote></div>   </div>  </div> </div></div>
 * 
     * Collection constructor
     * @link https://www.php.net/manual/en/mysql-xdevapi-collection.construct.php
     */
    public function __construct() {}

    /**
 * <div id="mysql-xdevapi-collection.add" class="refentry"> <div class="refnamediv">  <h1 class="refname">Collection::add</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">Collection::add</span> — <span class="dc-title">Add collection document</span></p> </div> <div class="refsect1 description" id="refsect1-mysql-xdevapi-collection.add-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\Collection::add</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$document</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mysql-xdevapi-collectionadd.php" class="type mysql_xdevapi\CollectionAdd" style="color:#EAB766">mysql_xdevapi\CollectionAdd</a></span></div>  <p class="para rdfs-comment">   Triggers the insertion of the given document(s) into the collection, and    multiple variants of this method are supported. Options include:  </p>  <ol type="1">   <li class="listitem">     <p class="para">      Add a single document as a JSON string.     </p>   </li>   <li class="listitem">     <p class="para">      Add a single document as an array as:       <span class="literal">[ 'field' =&gt; 'value', 'field2' =&gt; 'value2' ... ]</span>    </p>   </li>   <li class="listitem">    <p class="para">      A mix of both, and multiple documents can be added in the same operation.    </p>   </li>  </ol> </div> <div class="refsect1 parameters" id="refsect1-mysql-xdevapi-collection.add-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">document</span></dt>    <dd>     <p class="para">      One or multiple documents, and this can be either JSON or an array of fields with       their associated values. This cannot be an empty array.     </p>     <p class="para">      The MySQL server automatically generates unique <span class="literal">_id</span> values for      each document (recommended), although this can be manually added as well. This value must be      unique as otherwise the add operation will fail.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mysql-xdevapi-collection.add-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   A CollectionAdd object. Use execute() to return a Result that can be used to query the number    of affected items, the number warnings generated by the operation, or to fetch a list of    generated IDs for the inserted documents.  </p> </div> <div class="refsect1 examples" id="refsect1-mysql-xdevapi-collection.add-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">mysql_xdevapi\Collection::add()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$session </span><span style="color: #007700">= </span><span style="color: #9876AA">mysql_xdevapi\getSession</span><span style="color: #007700">(</span><span style="color: #DD0000">"mysqlx://user:password@localhost"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"DROP DATABASE IF EXISTS addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"CREATE DATABASE addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$schema </span><span style="color: #007700">= </span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getSchema</span><span style="color: #007700">(</span><span style="color: #DD0000">"addressbook"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$create </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$collection </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br><br></span><span style="color: #FF8000">// Add two documents<br></span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #DD0000">'{"name": "Fred",  "age": 21, "job": "Construction"}'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #DD0000">'{"name": "Wilma", "age": 23, "job": "Teacher"}'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #FF8000">// Add two documents using a single JSON object<br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(<br>  </span><span style="color: #DD0000">'{"name": "Bernie",<br>    "jobs": [{"title":"Cat Herder","Salary":42000}, {"title":"Father","Salary":0}],<br>    "hobbies": ["Sports","Making cupcakes"]}'</span><span style="color: #007700">,<br>  </span><span style="color: #DD0000">'{"name": "Jane",<br>    "jobs": [{"title":"Scientist","Salary":18000}, {"title":"Mother","Salary":0}],<br>    "hobbies": ["Walking","Making pies"]}'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #FF8000">// Fetch a list of generated ID's from the last add()<br></span><span style="color: #9876AA">\$ids </span><span style="color: #007700">= </span><span style="color: #9876AA">\$result</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getGeneratedIds</span><span style="color: #007700">();<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$ids</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Array<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;00005b6b53610000000000000056<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;00005b6b53610000000000000057<br>)</blockquote></div>   </div>  </div> </div> <div class="refsect1 notes" id="refsect1-mysql-xdevapi-collection.add-notes">  <h3 class="title">注释</h3>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    </p><p class="para">    A unique _id is generated by MySQL Server 8.0 or higher, as demonstrated     in the example. The _id field must be manually defined if using    MySQL Server 5.7.   </p>  </blockquote> </div> </div>
 * 
     * Add collection document
     * @link https://www.php.net/manual/en/mysql-xdevapi-collection.add.php
     * @param mixed $document
     * @return \mysql_xdevapi\CollectionAdd
     */
    public function add($document): CollectionAdd {}

    /**
 * <div id="mysql-xdevapi-collection.addorreplaceone" class="refentry"> <div class="refnamediv">  <h1 class="refname">Collection::addOrReplaceOne</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">Collection::addOrReplaceOne</span> — <span class="dc-title">Add or replace collection document</span></p> </div> <div class="refsect1 description" id="refsect1-mysql-xdevapi-collection.addorreplaceone-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\Collection::addOrReplaceOne</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$id</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$doc</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mysql-xdevapi-result.php" class="type mysql_xdevapi\Result" style="color:#EAB766">mysql_xdevapi\Result</a></span></div>  <p class="para rdfs-comment">   Add a new document, or replace a document if it already exists.  </p>  <p class="para">   Here are several scenarios for this method:  </p>  <ul class="itemizedlist">   <li class="listitem">    <p class="para">      If neither the id or any unique key values conflict with any document in the collection,       then the document is added.    </p>   </li>   <li class="listitem">    <p class="para">      If the id does not match any document but one or more unique key values conflict with a       document in the collection, then an error is raised.    </p>   </li>   <li class="listitem">    <p class="para">     If id matches an existing document and no unique keys are defined for the collection,      then the document is replaced.   </p>   </li>   <li class="listitem">    <p class="para">      If id matches an existing document, and either all unique keys in the replacement document       match that same document or they don't conflict with any other documents in the collection,       then the document is replaced.    </p>   </li>   <li class="listitem">    <p class="para">      If id matches an existing document and one or more unique keys match a different document       from the collection, then an error is raised.    </p>   </li>  </ul> </div> <div class="refsect1 parameters" id="refsect1-mysql-xdevapi-collection.addorreplaceone-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">id</span></dt>    <dd>     <p class="para">      This is the filter id. If this id or any other field that has a unique index already       exists in the collection, then it will update the matching document instead.     </p>     <p class="para">      By default, this id is automatically generated by MySQL Server when the      record was added, and is referenced as a field named '_id'.    </p>    </dd>          <dt><span class="parameter" style="color:#3A95FF">doc</span></dt>    <dd>     <p class="para">      This is the document to add or replace, which is a JSON string.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mysql-xdevapi-collection.addorreplaceone-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   A Result object.  </p> </div> <div class="refsect1 examples" id="refsect1-mysql-xdevapi-collection.addorreplaceone-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">mysql_xdevapi\Collection::addOrReplaceOne()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$session </span><span style="color: #007700">= </span><span style="color: #9876AA">mysql_xdevapi\getSession</span><span style="color: #007700">(</span><span style="color: #DD0000">"mysqlx://user:password@localhost"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"DROP DATABASE IF EXISTS addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"CREATE DATABASE addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$schema </span><span style="color: #007700">= </span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getSchema</span><span style="color: #007700">(</span><span style="color: #DD0000">"addressbook"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$create </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$collection </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br><br></span><span style="color: #FF8000">// Using add()<br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #DD0000">'{"name": "Wilma", "age": 23, "job": "Teacher"}'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #FF8000">// Using addOrReplaceOne()<br>// Note: we're passing in a known _id value here<br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">addOrReplaceOne</span><span style="color: #007700">(</span><span style="color: #DD0000">'00005b6b53610000000000000056'</span><span style="color: #007700">, </span><span style="color: #DD0000">'{"name": "Fred",  "age": 21, "job": "Construction"}'</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>  </div> </div></div>
 * 
     * Add or replace collection document
     * @link https://www.php.net/manual/en/mysql-xdevapi-collection.addorreplaceone.php
     * @param string $id
     * @param mixed $document
     * @return \mysql_xdevapi\Result
     */
    public function addOrReplaceOne($id, $document): Result {}

    /**
 * <div id="mysql-xdevapi-collection.count" class="refentry"> <div class="refnamediv">  <h1 class="refname">Collection::count</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">Collection::count</span> — <span class="dc-title">Get document count</span></p> </div> <div class="refsect1 description" id="refsect1-mysql-xdevapi-collection.count-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\Collection::count</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div>  <p class="para rdfs-comment">   This functionality is similar to a <span class="literal">SELECT COUNT(*)</span> SQL    operation against the MySQL server for the current schema and collection.   In other words, it counts the number of documents in the collection.  </p> </div> <div class="refsect1 parameters" id="refsect1-mysql-xdevapi-collection.count-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mysql-xdevapi-collection.count-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   The number of documents in the collection.  </p> </div> <div class="refsect1 examples" id="refsect1-mysql-xdevapi-collection.count-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">mysql_xdevapi\Collection::count()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$session </span><span style="color: #007700">= </span><span style="color: #9876AA">mysql_xdevapi\getSession</span><span style="color: #007700">(</span><span style="color: #DD0000">"mysqlx://user:password@localhost"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"DROP DATABASE IF EXISTS addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"CREATE DATABASE addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$schema </span><span style="color: #007700">= </span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getSchema</span><span style="color: #007700">(</span><span style="color: #DD0000">"addressbook"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$create </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$collection </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$collection<br>  </span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(<br>  </span><span style="color: #DD0000">'{"name": "Bernie",<br>    "jobs": [<br>      {"title":"Cat Herder","Salary":42000}, <br>      {"title":"Father","Salary":0}<br>    ],<br>    "hobbies": ["Sports","Making cupcakes"]}'</span><span style="color: #007700">,<br>  </span><span style="color: #DD0000">'{"name": "Jane",<br>    "jobs": [<br>      {"title":"Scientist","Salary":18000}, <br>      {"title":"Mother","Salary":0}<br>    ],<br>    "hobbies": ["Walking","Making pies"]}'</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">count</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">int(2)</blockquote></div>   </div>  </div> </div></div>
 * 
     * Get document count
     * @link https://www.php.net/manual/en/mysql-xdevapi-collection.count.php
     * @return int The number of documents in the collection.
     */
    public function count(): int {}

    /**
 * <div id="mysql-xdevapi-collection.createindex" class="refentry"> <div class="refnamediv">  <h1 class="refname">Collection::createIndex</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">Collection::createIndex</span> — <span class="dc-title">Create collection index</span></p> </div> <div class="refsect1 description" id="refsect1-mysql-xdevapi-collection.createindex-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\Collection::createIndex</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$index_name</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$index_desc_json</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="para rdfs-comment">    Creates an index on the collection.  </p>  <p class="para">    An exception is thrown if an index with the same name already exists,    or if index definition is not correctly formed.   </p> </div> <div class="refsect1 parameters" id="refsect1-mysql-xdevapi-collection.createindex-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">index_name</span></dt>    <dd>     <p class="para">      The name of the index that to create. This name must be a valid index name as       accepted by the <span class="literal">CREATE INDEX</span> SQL query.     </p>    </dd>          <dt><span class="parameter" style="color:#3A95FF">index_desc_json</span></dt>    <dd>     <p class="para">      Definition of the index to create. It contains an array of IndexField objects,      and each object describes a single document member to include in the index,       and an optional string for the type of index that might be INDEX (default) or SPATIAL.     </p>     <p class="para">      A single IndexField description consists of the following fields:     </p>     <ul class="itemizedlist">      <li class="listitem">        <p class="para">          <span class="code">field</span>: string, the full document path to the document member or field to be indexed.        </p>      </li>      <li class="listitem">       <p class="para">        <span class="code">type</span>: string, one of the supported SQL column types to map the field into.        For numeric types, the optional UNSIGNED keyword may follow.        For the TEXT type, the length to consider for indexing may be added.       </p>      </li>      <li class="listitem">        <p class="para">          <span class="code">required</span>: bool, (optional) true if the field is required to exist in the document.           Defaults to <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong>, except for <span class="literal">GEOJSON</span> where it defaults to <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>.         </p>       </li>      <li class="listitem">        <p class="para">          <span class="code">options</span>: integer, (optional) special option flags for use           when decoding <span class="literal">GEOJSON</span> data.        </p>      </li>      <li class="listitem">        <p class="para">          <span class="code">srid</span>: integer, (optional) srid value for use when           decoding <span class="literal">GEOJSON</span> data.        </p>      </li>      </ul>      <p class="para">        It is an error to include other fields not described above in         IndexDefinition or IndexField documents.      </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mysql-xdevapi-collection.createindex-returnvalues">  <h3 class="title">返回值</h3>  <p class="para"> </p></div> <div class="refsect1 examples" id="refsect1-mysql-xdevapi-collection.createindex-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">mysql_xdevapi\Collection::createIndex()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$session </span><span style="color: #007700">= </span><span style="color: #9876AA">mysql_xdevapi\getSession</span><span style="color: #007700">(</span><span style="color: #DD0000">"mysqlx://user:password@localhost"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"DROP DATABASE IF EXISTS addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"CREATE DATABASE addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$schema     </span><span style="color: #007700">= </span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getSchema</span><span style="color: #007700">(</span><span style="color: #DD0000">"addressbook"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$collection </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br><br></span><span style="color: #FF8000">// Creating a text index<br></span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createIndex</span><span style="color: #007700">(<br>  </span><span style="color: #DD0000">'myindex1'</span><span style="color: #007700">, <br>  </span><span style="color: #DD0000">'{"fields": [{<br>    "field": "\$.name", <br>    "type": "TEXT(25)", <br>    "required": true}], <br>    "unique": false}'<br></span><span style="color: #007700">);<br><br></span><span style="color: #FF8000">// A spatial index<br></span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createIndex</span><span style="color: #007700">(<br>  </span><span style="color: #DD0000">'myindex2'</span><span style="color: #007700">, <br>  </span><span style="color: #DD0000">'{"fields": [{<br>    "field": "\$.home", <br>    "type": "GEOJSON", <br>    "required": true}], <br>    "type": "SPATIAL"}'<br></span><span style="color: #007700">);<br><br></span><span style="color: #FF8000">// Index with multiple fields<br></span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createIndex</span><span style="color: #007700">(<br>  </span><span style="color: #DD0000">'myindex3'</span><span style="color: #007700">, <br>  </span><span style="color: #DD0000">'{"fields": [<br>    {<br>      "field": "\$.name",<br>      "type": "TEXT(20)",<br>      "required": true<br>    },<br>    {<br>      "field": "\$.age",<br>      "type": "INTEGER"<br>    },<br>    {<br>      "field": "\$.job",<br>      "type": "TEXT(30)",<br>      "required": false<br>    }<br>  ],<br>  "unique": true<br>  }'<br></span><span style="color: #007700">);</span></span></blockquote></div>   </div>  </div> </div></div>
 * 
     * Create collection index
     * @link https://www.php.net/manual/en/mysql-xdevapi-collection.createindex.php
     * @param string $index_name
     * @param string $index_desc_json
     */
    public function createIndex($index_name, $index_desc_json) {}

    /**
 * <div id="mysql-xdevapi-collection.dropindex" class="refentry"> <div class="refnamediv">  <h1 class="refname">Collection::dropIndex</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">Collection::dropIndex</span> — <span class="dc-title">Drop collection index</span></p> </div> <div class="refsect1 description" id="refsect1-mysql-xdevapi-collection.dropindex-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\Collection::dropIndex</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$index_name</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>  <p class="para rdfs-comment">   Drop a collection index.  </p>  <p class="para">   This operation does not yield an error if the index does not exist, but   <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> is returned in that case. </p> </div> <div class="refsect1 parameters" id="refsect1-mysql-xdevapi-collection.dropindex-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">index_name</span></dt>    <dd>     <p class="para">      Name of collection index to drop.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mysql-xdevapi-collection.dropindex-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> if the DROP INDEX operation succeeded, otherwise <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong>.  </p> </div> <div class="refsect1 examples" id="refsect1-mysql-xdevapi-collection.dropindex-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">mysql_xdevapi\Collection::dropIndex()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$session </span><span style="color: #007700">= </span><span style="color: #9876AA">mysql_xdevapi\getSession</span><span style="color: #007700">(</span><span style="color: #DD0000">"mysqlx://user:password@localhost"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"DROP DATABASE IF EXISTS addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"CREATE DATABASE addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$schema </span><span style="color: #007700">= </span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getSchema</span><span style="color: #007700">(</span><span style="color: #DD0000">"addressbook"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$create </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br><br></span><span style="color: #FF8000">// ...<br><br></span><span style="color: #9876AA">\$collection </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createIndex</span><span style="color: #007700">(<br>  </span><span style="color: #DD0000">'myindex'</span><span style="color: #007700">, <br>  </span><span style="color: #DD0000">'{"fields": [{"field": "\$.name", "type": "TEXT(25)", "required": true}], "unique": false}'<br></span><span style="color: #007700">);<br><br></span><span style="color: #FF8000">// ...<br><br></span><span style="color: #007700">if (</span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">dropIndex</span><span style="color: #007700">(</span><span style="color: #DD0000">'myindex'</span><span style="color: #007700">)) {<br>    echo </span><span style="color: #DD0000">"An index named 'myindex' was found, and dropped."</span><span style="color: #007700">;<br>}<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">An&nbsp;index&nbsp;named&nbsp;'myindex'&nbsp;was&nbsp;found,&nbsp;and&nbsp;dropped.</blockquote></div>   </div>  </div> </div></div>
 * 
     * Drop collection index
     * @link https://www.php.net/manual/en/mysql-xdevapi-collection.dropindex.php
     * @param string $index_name
     * @return bool
     */
    public function dropIndex($index_name): bool {}

    /**
 * <div id="mysql-xdevapi-collection.existsindatabase" class="refentry"> <div class="refnamediv">  <h1 class="refname">Collection::existsInDatabase</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">Collection::existsInDatabase</span> — <span class="dc-title">Check if collection exists in database</span></p> </div> <div class="refsect1 description" id="refsect1-mysql-xdevapi-collection.existsindatabase-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\Collection::existsInDatabase</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>  <p class="para rdfs-comment">   Checks if the Collection object refers to a collection in the database (schema).  </p> </div> <div class="refsect1 parameters" id="refsect1-mysql-xdevapi-collection.existsindatabase-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mysql-xdevapi-collection.existsindatabase-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   Returns <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> if collection exists in the database, else <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> if it does not.  </p>  <p class="para">    A table defined with two columns (doc and _id) is considered a collection,     and a third _json_schema column as of MySQL 8.0.21.     Adding an additional column means existsInDatabase() will no longer see it as a collection.  </p> </div> <div class="refsect1 examples" id="refsect1-mysql-xdevapi-collection.existsindatabase-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">mysql_xdevapi\Collection::existsInDatabase()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$session </span><span style="color: #007700">= </span><span style="color: #9876AA">mysql_xdevapi\getSession</span><span style="color: #007700">(</span><span style="color: #DD0000">"mysqlx://user:password@localhost"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"DROP DATABASE IF EXISTS addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"CREATE DATABASE addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$schema </span><span style="color: #007700">= </span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getSchema</span><span style="color: #007700">(</span><span style="color: #DD0000">"addressbook"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$create </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br><br></span><span style="color: #FF8000">// ...<br><br></span><span style="color: #9876AA">\$collection </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br><br></span><span style="color: #FF8000">// ...<br><br></span><span style="color: #007700">if (!</span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">existsInDatabase</span><span style="color: #007700">()) {<br>    echo </span><span style="color: #DD0000">"The collection no longer exists in the database named addressbook. What happened?"</span><span style="color: #007700">;<br>}<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>  </div> </div></div>
 * 
     * Check if collection exists in database
     * @link https://www.php.net/manual/en/mysql-xdevapi-collection.existsindatabase.php
     * @return bool
     */
    public function existsInDatabase(): bool {}

    /**
 * <div id="mysql-xdevapi-collection.find" class="refentry"> <div class="refnamediv">  <h1 class="refname">Collection::find</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">Collection::find</span> — <span class="dc-title">Search for document</span></p> </div> <div class="refsect1 description" id="refsect1-mysql-xdevapi-collection.find-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\Collection::find</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$search_condition</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mysql-xdevapi-collectionfind.php" class="type mysql_xdevapi\CollectionFind" style="color:#EAB766">mysql_xdevapi\CollectionFind</a></span></div>  <p class="para rdfs-comment">   Search a database collection for a document or set of documents. The   found documents are returned as a CollectionFind object is to   further modify or fetch results from.  </p> </div> <div class="refsect1 parameters" id="refsect1-mysql-xdevapi-collection.find-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">search_condition</span></dt>    <dd>     <p class="para">      Although optional, normally a condition is defined to limit the results      to a subset of documents.     </p>     <p class="para">      Multiple elements might build the condition and the syntax supports parameter binding.       The expression used as search condition must be a valid SQL expression.      If no search condition is provided (field empty) then find('true') is assumed.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mysql-xdevapi-collection.find-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   A CollectionFind object to verify the operation,   or fetch the found documents.  </p> </div> <div class="refsect1 examples" id="refsect1-mysql-xdevapi-collection.find-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">mysql_xdevapi\Collection::find()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$session </span><span style="color: #007700">= </span><span style="color: #9876AA">mysql_xdevapi\getSession</span><span style="color: #007700">(</span><span style="color: #DD0000">"mysqlx://user:password@localhost"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"DROP DATABASE IF EXISTS addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"CREATE DATABASE addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$schema     </span><span style="color: #007700">= </span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getSchema</span><span style="color: #007700">(</span><span style="color: #DD0000">"addressbook"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$collection </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #DD0000">'{"name": "Alfred",     "age": 18, "job": "Butler"}'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #DD0000">'{"name": "Bob",        "age": 19, "job": "Swimmer"}'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #DD0000">'{"name": "Fred",       "age": 20, "job": "Construction"}'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #DD0000">'{"name": "Wilma",      "age": 21, "job": "Teacher"}'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #DD0000">'{"name": "Suki",       "age": 22, "job": "Teacher"}'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$find   </span><span style="color: #007700">= </span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">find</span><span style="color: #007700">(</span><span style="color: #DD0000">'job LIKE :job AND age &gt; :age'</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$find<br>  </span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">bind</span><span style="color: #007700">([</span><span style="color: #DD0000">'job' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'Teacher'</span><span style="color: #007700">, </span><span style="color: #DD0000">'age' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">20</span><span style="color: #007700">])<br>  -&gt;</span><span style="color: #9876AA">sort</span><span style="color: #007700">(</span><span style="color: #DD0000">'age DESC'</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">limit</span><span style="color: #007700">(</span><span style="color: #9876AA">2</span><span style="color: #007700">)            <br>  -&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$result</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">fetchAll</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Array<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;Array<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[_id]&nbsp;=&gt;&nbsp;00005b6b536100000000000000a8<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[age]&nbsp;=&gt;&nbsp;22<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[job]&nbsp;=&gt;&nbsp;Teacher<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[name]&nbsp;=&gt;&nbsp;Suki<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;)<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;Array<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[_id]&nbsp;=&gt;&nbsp;00005b6b536100000000000000a7<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[age]&nbsp;=&gt;&nbsp;21<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[job]&nbsp;=&gt;&nbsp;Teacher<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[name]&nbsp;=&gt;&nbsp;Wilma<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;)<br>)</blockquote></div>   </div>  </div> </div></div>
 * 
     * @link https://secure.php.net/manual/en/mysql-xdevapi-collection.find.php
     * @param string $search_condition
     * @return \mysql_xdevapi\CollectionFind
     */
    public function find($search_condition): CollectionFind {}

    /**
 * <div id="mysql-xdevapi-collection.getname" class="refentry"> <div class="refnamediv">  <h1 class="refname">Collection::getName</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">Collection::getName</span> — <span class="dc-title">Get collection name</span></p> </div> <div class="refsect1 description" id="refsect1-mysql-xdevapi-collection.getname-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\Collection::getName</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div>  <p class="para rdfs-comment">   Retrieve the collection's name.  </p> </div> <div class="refsect1 parameters" id="refsect1-mysql-xdevapi-collection.getname-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mysql-xdevapi-collection.getname-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   The collection name, as a string.  </p> </div> <div class="refsect1 examples" id="refsect1-mysql-xdevapi-collection.getname-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">mysql_xdevapi\Collection::getName()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$session </span><span style="color: #007700">= </span><span style="color: #9876AA">mysql_xdevapi\getSession</span><span style="color: #007700">(</span><span style="color: #DD0000">"mysqlx://user:password@localhost"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"DROP DATABASE IF EXISTS addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"CREATE DATABASE addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$schema     </span><span style="color: #007700">= </span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getSchema</span><span style="color: #007700">(</span><span style="color: #DD0000">"addressbook"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$collection </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br><br><br></span><span style="color: #FF8000">// ...<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getName</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">string(6)&nbsp;"people"</blockquote></div>   </div>  </div> </div> </div>
 * 
