    /**
 * <div id="mysql-xdevapi-collection.modify" class="refentry"> <div class="refnamediv">  <h1 class="refname">Collection::modify</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">Collection::modify</span> — <span class="dc-title">Modify collection documents</span></p> </div> <div class="refsect1 description" id="refsect1-mysql-xdevapi-collection.modify-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\Collection::modify</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$search_condition</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mysql-xdevapi-collectionmodify.php" class="type mysql_xdevapi\CollectionModify" style="color:#EAB766">mysql_xdevapi\CollectionModify</a></span></div>  <p class="para rdfs-comment">   Modify the documents of a collection that meet specific search conditions.   Multiple operations are allowed, and parameter binding   is supported.  </p> </div> <div class="refsect1 parameters" id="refsect1-mysql-xdevapi-collection.modify-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">search_condition</span></dt>    <dd>     <p class="para">      Must be a valid SQL expression used to match the documents to modify.      This expression might be as simple as <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>, which matches all       documents, or it might use functions and operators such as       <span class="code">'CAST(_id AS SIGNED) &gt;= 10'</span>,       <span class="code">'age MOD 2 = 0 OR age MOD 3 = 0'</span>, or      <span class="code">'_id IN ["2","5","7","10"]'</span>.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mysql-xdevapi-collection.modify-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   If the operation is not executed, then the function will return    a Modify object that can be used to add additional   modify operations.  </p>  <p class="para">   If the modify operation is executed, then the returned object will contain   the result of the operation.  </p> </div> <div class="refsect1 examples" id="refsect1-mysql-xdevapi-collection.modify-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">mysql_xdevapi\Collection::modify()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$session </span><span style="color: #007700">= </span><span style="color: #9876AA">mysql_xdevapi\getSession</span><span style="color: #007700">(</span><span style="color: #DD0000">"mysqlx://user:password@localhost"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"DROP DATABASE IF EXISTS addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"CREATE DATABASE addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$schema     </span><span style="color: #007700">= </span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getSchema</span><span style="color: #007700">(</span><span style="color: #DD0000">"addressbook"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$collection </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #DD0000">'{"name": "Alfred", "age": 18, "job": "Butler"}'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #DD0000">'{"name": "Bob",    "age": 19, "job": "Painter"}'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #FF8000">// Add two new jobs for all Painters: Artist and Crafter<br></span><span style="color: #9876AA">\$collection<br>  </span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">modify</span><span style="color: #007700">(</span><span style="color: #DD0000">"job in ('Butler', 'Painter')"</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">arrayAppend</span><span style="color: #007700">(</span><span style="color: #DD0000">'job'</span><span style="color: #007700">, </span><span style="color: #DD0000">'Artist'</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">arrayAppend</span><span style="color: #007700">(</span><span style="color: #DD0000">'job'</span><span style="color: #007700">, </span><span style="color: #DD0000">'Crafter'</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #FF8000">// Remove the 'beer' field from all documents with the age 21<br></span><span style="color: #9876AA">\$collection<br>  </span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">modify</span><span style="color: #007700">(</span><span style="color: #DD0000">'age &lt; 21'</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">unset</span><span style="color: #007700">([</span><span style="color: #DD0000">'beer'</span><span style="color: #007700">])<br>  -&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>  </div> </div></div>
 * 
     * Modify collections that meet specific search conditions. Multiple operations are allowed, and parameter binding is supported.
     * @link https://www.php.net/manual/en/mysql-xdevapi-collection.modify.php
     * @param string $search_condition
     * @return \mysql_xdevapi\CollectionModify
     */
    public function modify($search_condition): CollectionModify {}

    /**
 * <div id="mysql-xdevapi-collection.remove" class="refentry"> <div class="refnamediv">  <h1 class="refname">Collection::remove</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">Collection::remove</span> — <span class="dc-title">Remove collection documents</span></p> </div> <div class="refsect1 description" id="refsect1-mysql-xdevapi-collection.remove-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\Collection::remove</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$search_condition</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mysql-xdevapi-collectionremove.php" class="type mysql_xdevapi\CollectionRemove" style="color:#EAB766">mysql_xdevapi\CollectionRemove</a></span></div>  <p class="para rdfs-comment">   Removes documents of a collection that meet specific search conditions.   Multiple operations are allowed, and parameter binding is supported.  </p> </div> <div class="refsect1 parameters" id="refsect1-mysql-xdevapi-collection.remove-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">search_condition</span></dt>    <dd>     <p class="para">      Must be a valid SQL expression used to match the documents to remove.      This expression might be as simple as <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>, which matches all       documents, or it might use functions and operators such as       <span class="code">'CAST(_id AS SIGNED) &gt;= 10'</span>,       <span class="code">'age MOD 2 = 0 OR age MOD 3 = 0'</span>, or      <span class="code">'_id IN ["2","5","7","10"]'</span>.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mysql-xdevapi-collection.remove-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   If the operation is not executed, then the function will return    a Remove object that can be used to add additional   remove operations.  </p>  <p class="para">   If the remove operation is executed, then the returned object will contain   the result of the operation.  </p> </div> <div class="refsect1 examples" id="refsect1-mysql-xdevapi-collection.remove-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">mysql_xdevapi\Collection::remove()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$session </span><span style="color: #007700">= </span><span style="color: #9876AA">mysql_xdevapi\getSession</span><span style="color: #007700">(</span><span style="color: #DD0000">"mysqlx://user:password@localhost"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"DROP DATABASE IF EXISTS addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"CREATE DATABASE addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$schema     </span><span style="color: #007700">= </span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getSchema</span><span style="color: #007700">(</span><span style="color: #DD0000">"addressbook"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$collection </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #DD0000">'{"name": "Alfred", "age": 18, "job": "Butler"}'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #DD0000">'{"name": "Bob",    "age": 19, "job": "Painter"}'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #FF8000">// Remove all painters<br></span><span style="color: #9876AA">\$collection<br>  </span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">remove</span><span style="color: #007700">(</span><span style="color: #DD0000">"job in ('Painter')"</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #FF8000">// Remove the oldest butler<br></span><span style="color: #9876AA">\$collection<br>  </span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">remove</span><span style="color: #007700">(</span><span style="color: #DD0000">"job in ('Butler')"</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">sort</span><span style="color: #007700">(</span><span style="color: #DD0000">'age desc'</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">limit</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #FF8000">// Remove record with highest age<br></span><span style="color: #9876AA">\$collection<br>  </span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">remove</span><span style="color: #007700">(</span><span style="color: #DD0000">'true'</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">sort</span><span style="color: #007700">(</span><span style="color: #DD0000">'age desc'</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">limit</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>  </div> </div></div>
 * 
     * Remove collections that meet specific search conditions. Multiple operations are allowed, and parameter binding is supported.
     * @link https://www.php.net/manual/en/mysql-xdevapi-collection.remove.php
     * @param string $search_condition
     * @return \mysql_xdevapi\CollectionRemove
     */
    public function remove($search_condition): CollectionRemove {}

    /**
 * <div id="mysql-xdevapi-collection.removeone" class="refentry"> <div class="refnamediv">  <h1 class="refname">Collection::removeOne</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">Collection::removeOne</span> — <span class="dc-title">Remove one collection document</span></p> </div> <div class="refsect1 description" id="refsect1-mysql-xdevapi-collection.removeone-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\Collection::removeOne</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$id</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mysql-xdevapi-result.php" class="type mysql_xdevapi\Result" style="color:#EAB766">mysql_xdevapi\Result</a></span></div>  <p class="para rdfs-comment">   Remove one document from the collection with the corresponding ID.   This is a shortcut for <span class="code">Collection.remove("_id = :id").bind("id", id).execute()</span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-mysql-xdevapi-collection.removeone-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">id</span></dt>    <dd>     <p class="para">      The ID of the collection document to remove. Typically this is      the _id that was generated by MySQL Server when the record      was added.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mysql-xdevapi-collection.removeone-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   A Result object that can be used to query the number of affected items or the   number warnings generated by the operation.  </p> </div> <div class="refsect1 examples" id="refsect1-mysql-xdevapi-collection.removeone-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">mysql_xdevapi\Collection::removeOne()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$session </span><span style="color: #007700">= </span><span style="color: #9876AA">mysql_xdevapi\getSession</span><span style="color: #007700">(</span><span style="color: #DD0000">"mysqlx://user:password@localhost"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"DROP DATABASE IF EXISTS addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"CREATE DATABASE addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$schema     </span><span style="color: #007700">= </span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getSchema</span><span style="color: #007700">(</span><span style="color: #DD0000">"addressbook"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$collection </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #DD0000">'{"name": "Alfred", "age": 18, "job": "Butler"}'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #FF8000">// Normally the _id is known by other means, <br>// but for this example let's fetch the generated id and use it<br></span><span style="color: #9876AA">\$ids       </span><span style="color: #007700">= </span><span style="color: #9876AA">\$result</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getGeneratedIds</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$alfred_id </span><span style="color: #007700">= </span><span style="color: #9876AA">\$ids</span><span style="color: #007700">[</span><span style="color: #9876AA">0</span><span style="color: #007700">];<br><br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">removeOne</span><span style="color: #007700">(</span><span style="color: #9876AA">\$alfred_id</span><span style="color: #007700">);<br><br>if(!</span><span style="color: #9876AA">\$result</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getAffectedItemsCount</span><span style="color: #007700">()) {<br>    echo </span><span style="color: #DD0000">"Alfred with id </span><span style="color: #9876AA">\$alfred_id</span><span style="color: #DD0000"> was not removed."</span><span style="color: #007700">;<br>} else {<br>    echo </span><span style="color: #DD0000">"Goodbye, Alfred, you can take _id </span><span style="color: #9876AA">\$alfred_id</span><span style="color: #DD0000"> with you."</span><span style="color: #007700">;<br>}<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Goodbye,&nbsp;Alfred,&nbsp;you&nbsp;can&nbsp;take&nbsp;_id&nbsp;00005b6b536100000000000000cb&nbsp;with&nbsp;you.</blockquote></div>   </div>  </div> </div> </div>
 * 
     * Remove one collection document
     * Remove one document from the collection with the corresponding ID. This is a shortcut for Collection.remove("_id = :id").bind("id", id).execute().
     * @link https://www.php.net/manual/en/mysql-xdevapi-collection.removeone.php
     * @param string $id
     * @return \mysql_xdevapi\Result
     */
    public function removeOne($id): Result {}

    /**
 * <div id="mysql-xdevapi-collection.replaceone" class="refentry"> <div class="refnamediv">  <h1 class="refname">Collection::replaceOne</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">Collection::replaceOne</span> — <span class="dc-title">Replace one collection document</span></p> </div> <div class="refsect1 description" id="refsect1-mysql-xdevapi-collection.replaceone-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\Collection::replaceOne</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$id</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$doc</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mysql-xdevapi-result.php" class="type mysql_xdevapi\Result" style="color:#EAB766">mysql_xdevapi\Result</a></span></div>  <p class="para rdfs-comment">   Updates (or replaces) the document identified by ID, if it exists.  </p> </div> <div class="refsect1 parameters" id="refsect1-mysql-xdevapi-collection.replaceone-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">id</span></dt>    <dd>     <p class="para">      ID of the document to replace or update. Typically this is      the _id that was generated by MySQL Server when the record      was added.     </p>    </dd>          <dt><span class="parameter" style="color:#3A95FF">doc</span></dt>    <dd>     <p class="para">      Collection document to update or replace the document matching      the <strong class="option unknown">id</strong> parameter.     </p>     <p class="para">      This document can be either a document object or a valid JSON string       describing the new document.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mysql-xdevapi-collection.replaceone-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   A Result object that can be used to query the number of affected items and the   number warnings generated by the operation.  </p> </div> <div class="refsect1 examples" id="refsect1-mysql-xdevapi-collection.replaceone-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">mysql_xdevapi\Collection::replaceOne()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$session </span><span style="color: #007700">= </span><span style="color: #9876AA">mysql_xdevapi\getSession</span><span style="color: #007700">(</span><span style="color: #DD0000">"mysqlx://user:password@localhost"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"DROP DATABASE IF EXISTS addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"CREATE DATABASE addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$schema     </span><span style="color: #007700">= </span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getSchema</span><span style="color: #007700">(</span><span style="color: #DD0000">"addressbook"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$collection </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #DD0000">'{"name": "Alfred", "age": 18, "job": "Butler"}'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #FF8000">// Normally the _id is known by other means, <br>// but for this example let's fetch the generated id and use it<br></span><span style="color: #9876AA">\$ids       </span><span style="color: #007700">= </span><span style="color: #9876AA">\$result</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getGeneratedIds</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$alfred_id </span><span style="color: #007700">= </span><span style="color: #9876AA">\$ids</span><span style="color: #007700">[</span><span style="color: #9876AA">0</span><span style="color: #007700">];<br><br></span><span style="color: #FF8000">// ...<br><br></span><span style="color: #9876AA">\$alfred </span><span style="color: #007700">= </span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getOne</span><span style="color: #007700">(</span><span style="color: #9876AA">\$alfred_id</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$alfred</span><span style="color: #007700">[</span><span style="color: #DD0000">'age'</span><span style="color: #007700">] = </span><span style="color: #9876AA">81</span><span style="color: #007700">;<br></span><span style="color: #9876AA">\$alfred</span><span style="color: #007700">[</span><span style="color: #DD0000">'job'</span><span style="color: #007700">] = </span><span style="color: #DD0000">'Guru'</span><span style="color: #007700">;<br><br></span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">replaceOne</span><span style="color: #007700">(</span><span style="color: #9876AA">\$alfred_id</span><span style="color: #007700">, </span><span style="color: #9876AA">\$alfred</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>  </div> </div></div>
