    /**
 * <div id="mysql-xdevapi-collectionfind.bind" class="refentry"> <div class="refnamediv">  <h1 class="refname">CollectionFind::bind</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">CollectionFind::bind</span> — <span class="dc-title">Bind value to query placeholder</span></p> </div> <div class="refsect1 description" id="refsect1-mysql-xdevapi-collectionfind.bind-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\CollectionFind::bind</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> <span class="parameter" style="color:#3A95FF">\$placeholder_values</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mysql-xdevapi-collectionfind.php" class="type mysql_xdevapi\CollectionFind" style="color:#EAB766">mysql_xdevapi\CollectionFind</a></span></div>  <p class="para rdfs-comment">   It allows the user to bind a parameter to the placeholder in the search condition of the find operation.   The placeholder has the form of :NAME where ':' is a common prefix that must always exists before any NAME,   NAME is the actual name of the placeholder. The bind function accepts a list of placeholders if multiple   entities have to be substituted in the search condition.  </p> </div> <div class="refsect1 parameters" id="refsect1-mysql-xdevapi-collectionfind.bind-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">placeholder_values</span></dt>    <dd>     <p class="para">      Values to substitute in the search condition; multiple values are allowed      and are passed as an array where "PLACEHOLDER_NAME =&gt; PLACEHOLDER_VALUE".     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mysql-xdevapi-collectionfind.bind-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   A CollectionFind object,    or chain with execute() to return a Result object.  </p> </div> <div class="refsect1 examples" id="refsect1-mysql-xdevapi-collectionfind.bind-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">mysql_xdevapi\CollectionFind::bind()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$session </span><span style="color: #007700">= </span><span style="color: #9876AA">mysql_xdevapi\getSession</span><span style="color: #007700">(</span><span style="color: #DD0000">"mysqlx://user:password@localhost"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"DROP DATABASE IF EXISTS addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"CREATE DATABASE addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$schema </span><span style="color: #007700">= </span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getSchema</span><span style="color: #007700">(</span><span style="color: #DD0000">"addressbook"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$create </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$create<br>  </span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #DD0000">'{"name": "Alfred", "age": 18, "job": "Butler"}'</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #FF8000">// ...<br><br></span><span style="color: #9876AA">\$collection </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$collection<br>  </span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">find</span><span style="color: #007700">(</span><span style="color: #DD0000">'job like :job and age &gt; :age'</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">bind</span><span style="color: #007700">([</span><span style="color: #DD0000">'job' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'Butler'</span><span style="color: #007700">, </span><span style="color: #DD0000">'age' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">16</span><span style="color: #007700">])<br>  -&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$result</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">fetchAll</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">array(1)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;array(4)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["_id"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(28)&nbsp;"00005b6b536100000000000000cf"<br>&nbsp;&nbsp;&nbsp;&nbsp;["age"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(18)<br>&nbsp;&nbsp;&nbsp;&nbsp;["job"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(6)&nbsp;"Butler"<br>&nbsp;&nbsp;&nbsp;&nbsp;["name"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(6)&nbsp;"Alfred"<br>&nbsp;&nbsp;}<br>}</blockquote></div>   </div>  </div> </div></div>
 * 
     * Bind value to query placeholder
     * It allows the user to bind a parameter to the placeholder in the search condition of the find operation. The placeholder has the form of :NAME where ':' is a common prefix that must always exists before any NAME, NAME is the actual name of the placeholder. The bind function accepts a list of placeholders if multiple entities have to be substituted in the search condition.
     * @link https://www.php.net/manual/en/mysql-xdevapi-collectionfind.bind.php
     * @param array $placeholder_values
     * @return \mysql_xdevapi\CollectionFind
     */
    public function bind(array $placeholder_values): CollectionFind {}

    /**
 * <div id="mysql-xdevapi-collectionfind.execute" class="refentry"> <div class="refnamediv">  <h1 class="refname">CollectionFind::execute</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">CollectionFind::execute</span> — <span class="dc-title">Execute the statement</span></p> </div> <div class="refsect1 description" id="refsect1-mysql-xdevapi-collectionfind.execute-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\CollectionFind::execute</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mysql-xdevapi-docresult.php" class="type mysql_xdevapi\DocResult" style="color:#EAB766">mysql_xdevapi\DocResult</a></span></div>  <p class="para rdfs-comment">   Execute the find operation;   this functionality allows for method chaining.  </p> </div> <div class="refsect1 parameters" id="refsect1-mysql-xdevapi-collectionfind.execute-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mysql-xdevapi-collectionfind.execute-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   A <span class="classname"><a href="https://php.net/manual/zh/class.mysql-xdevapi-docresult.php" class="classname">mysql_xdevapi\DocResult</a></span> object that can be used   to either fetch results from, or to query the status of the operation.  </p> </div> <div class="refsect1 examples" id="refsect1-mysql-xdevapi-collectionfind.execute-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 CollectionFind example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$session </span><span style="color: #007700">= </span><span style="color: #9876AA">mysql_xdevapi\getSession</span><span style="color: #007700">(</span><span style="color: #DD0000">"mysqlx://user:password@localhost"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"DROP DATABASE IF EXISTS addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"CREATE DATABASE addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$schema </span><span style="color: #007700">= </span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getSchema</span><span style="color: #007700">(</span><span style="color: #DD0000">"addressbook"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$create </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$create<br>  </span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #DD0000">'{"name": "Alfred", "age": 18, "job": "Butler"}'</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #FF8000">// ...<br><br></span><span style="color: #9876AA">\$collection </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$collection<br>  </span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">find</span><span style="color: #007700">(</span><span style="color: #DD0000">'job like :job and age &gt; :age'</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">bind</span><span style="color: #007700">([</span><span style="color: #DD0000">'job' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'Butler'</span><span style="color: #007700">, </span><span style="color: #DD0000">'age' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">16</span><span style="color: #007700">])<br>  -&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$result</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">fetchAll</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">array(1)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;array(4)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["_id"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(28)&nbsp;"00005b6b536100000000000000cf"<br>&nbsp;&nbsp;&nbsp;&nbsp;["age"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(18)<br>&nbsp;&nbsp;&nbsp;&nbsp;["job"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(6)&nbsp;"Butler"<br>&nbsp;&nbsp;&nbsp;&nbsp;["name"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(6)&nbsp;"Alfred"<br>&nbsp;&nbsp;}<br>}</blockquote></div>   </div>  </div> </div></div>
 * 
