or: #007700">-&gt;</span><span style="color: #9876AA">createCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$create<br>  </span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #DD0000">'{"name": "Alfred", "age": 18, "job": "Butler"}'</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #FF8000">// ...<br><br></span><span style="color: #9876AA">\$collection </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$collection<br>  </span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">find</span><span style="color: #007700">(</span><span style="color: #DD0000">'job like :job and age &gt; :age'</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">bind</span><span style="color: #007700">([</span><span style="color: #DD0000">'job' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'Butler'</span><span style="color: #007700">, </span><span style="color: #DD0000">'age' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">16</span><span style="color: #007700">])<br>  -&gt;</span><span style="color: #9876AA">fields</span><span style="color: #007700">(</span><span style="color: #DD0000">'name'</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$result</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">fetchAll</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">array(1)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;array(1)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["name"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(6)&nbsp;"Alfred"<br>&nbsp;&nbsp;}<br>}</blockquote></div>   </div>  </div> </div></div>
