    /**
 * <div id="mysql-xdevapi-collectionfind.groupby" class="refentry"> <div class="refnamediv">  <h1 class="refname">CollectionFind::groupBy</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">CollectionFind::groupBy</span> — <span class="dc-title">Set grouping criteria</span></p> </div> <div class="refsect1 description" id="refsect1-mysql-xdevapi-collectionfind.groupby-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\CollectionFind::groupBy</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$sort_expr</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mysql-xdevapi-collectionfind.php" class="type mysql_xdevapi\CollectionFind" style="color:#EAB766">mysql_xdevapi\CollectionFind</a></span></div>  <p class="para rdfs-comment">   This function can be used to group the result set by one or more columns.   It is often used with aggregate functions such as <span class="literal">COUNT</span>,   <span class="literal">MAX</span>, <span class="literal">MIN</span>, <span class="literal">SUM</span> etc.  </p> </div> <div class="refsect1 parameters" id="refsect1-mysql-xdevapi-collectionfind.groupby-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">sort_expr</span></dt>    <dd>     <p class="para">      The column or columns that have to be used for the group operation, this can either be a single string      or an array of string arguments, one for each column.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mysql-xdevapi-collectionfind.groupby-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   A CollectionFind object that can be used for further processing.  </p> </div> <div class="refsect1 examples" id="refsect1-mysql-xdevapi-collectionfind.groupby-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">mysql_xdevapi\CollectionFind::groupBy()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br></span><span style="color: #FF8000">// Assuming \$coll is a valid Collection object<br><br>// Extract all the documents from the Collection and group the results by the 'name' field<br></span><span style="color: #9876AA">\$res </span><span style="color: #007700">= </span><span style="color: #9876AA">\$coll</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">find</span><span style="color: #007700">()-&gt;</span><span style="color: #9876AA">groupBy</span><span style="color: #007700">(</span><span style="color: #DD0000">'name'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>  </div> </div></div>
