     */
    public function groupBy(string $sort_expr): CollectionFind {}

    /**
 * <div id="mysql-xdevapi-collectionfind.having" class="refentry"> <div class="refnamediv">  <h1 class="refname">CollectionFind::having</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">CollectionFind::having</span> — <span class="dc-title">Set condition for aggregate functions</span></p> </div> <div class="refsect1 description" id="refsect1-mysql-xdevapi-collectionfind.having-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\CollectionFind::having</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$sort_expr</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mysql-xdevapi-collectionfind.php" class="type mysql_xdevapi\CollectionFind" style="color:#EAB766">mysql_xdevapi\CollectionFind</a></span></div>  <p class="para rdfs-comment">   This function can be used after the 'field' operation in order to make a selection on the documents to extract.  </p> </div> <div class="refsect1 parameters" id="refsect1-mysql-xdevapi-collectionfind.having-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">sort_expr</span></dt>    <dd>     <p class="para">      This must be a valid SQL expression, the use of aggreate functions is allowed     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mysql-xdevapi-collectionfind.having-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">  CollectionFind object that can be used for further processing   </p> </div> <div class="refsect1 examples" id="refsect1-mysql-xdevapi-collectionfind.having-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">mysql_xdevapi\CollectionFind::having()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br></span><span style="color: #FF8000">//Assuming \$coll is a valid Collection object<br><br>//Find all the documents for which the 'age' is greather than 40,<br>//Only the columns 'name' and 'age' are returned in the Result object<br></span><span style="color: #9876AA">\$res </span><span style="color: #007700">= </span><span style="color: #9876AA">\$coll</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">find</span><span style="color: #007700">()-&gt;</span><span style="color: #9876AA">fields</span><span style="color: #007700">([</span><span style="color: #DD0000">'name'</span><span style="color: #007700">,</span><span style="color: #DD0000">'age'</span><span style="color: #007700">])-&gt;</span><span style="color: #9876AA">having</span><span style="color: #007700">(</span><span style="color: #DD0000">'age &gt; 40'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>  </div> </div></div>
