     * @param string $sort_expr
     * @return \mysql_xdevapi\CollectionFind
     */
    public function having(string $sort_expr): CollectionFind {}

    /**
 * <div id="mysql-xdevapi-collectionfind.limit" class="refentry"> <div class="refnamediv">  <h1 class="refname">CollectionFind::limit</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">CollectionFind::limit</span> — <span class="dc-title">Limit number of returned documents</span></p> </div> <div class="refsect1 description" id="refsect1-mysql-xdevapi-collectionfind.limit-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\CollectionFind::limit</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$rows</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mysql-xdevapi-collectionfind.php" class="type mysql_xdevapi\CollectionFind" style="color:#EAB766">mysql_xdevapi\CollectionFind</a></span></div>  <p class="para rdfs-comment">   Set the maximum number of documents to return.  </p> </div> <div class="refsect1 parameters" id="refsect1-mysql-xdevapi-collectionfind.limit-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">rows</span></dt>    <dd>     <p class="para">      Maximum number of documents.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mysql-xdevapi-collectionfind.limit-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   A CollectionFind object that can be used for additional processing;   chain with the execute() method to return a DocResult object.  </p> </div> <div class="refsect1 examples" id="refsect1-mysql-xdevapi-collectionfind.limit-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">mysql_xdevapi\CollectionFind::limit()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$session </span><span style="color: #007700">= </span><span style="color: #9876AA">mysql_xdevapi\getSession</span><span style="color: #007700">(</span><span style="color: #DD0000">"mysqlx://user:password@localhost"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"DROP DATABASE IF EXISTS addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"CREATE DATABASE addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$schema </span><span style="color: #007700">= </span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getSchema</span><span style="color: #007700">(</span><span style="color: #DD0000">"addressbook"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$create </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$create<br>  </span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #DD0000">'{"name": "Alfred", "age": 18, "job": "Butler"}'</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$create<br>  </span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #DD0000">'{"name": "Reginald", "age": 42, "job": "Butler"}'</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br><br></span><span style="color: #FF8000">// ...<br><br></span><span style="color: #9876AA">\$collection </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$collection<br>  </span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">find</span><span style="color: #007700">(</span><span style="color: #DD0000">'job like :job and age &gt; :age'</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">bind</span><span style="color: #007700">([</span><span style="color: #DD0000">'job' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'Butler'</span><span style="color: #007700">, </span><span style="color: #DD0000">'age' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">16</span><span style="color: #007700">])<br>  -&gt;</span><span style="color: #9876AA">sort</span><span style="color: #007700">(</span><span style="color: #DD0000">'age desc'</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">limit</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$result</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">fetchAll</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">array(1)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;array(4)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["_id"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(28)&nbsp;"00005b6b536100000000000000f3"<br>&nbsp;&nbsp;&nbsp;&nbsp;["age"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(42)<br>&nbsp;&nbsp;&nbsp;&nbsp;["job"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(6)&nbsp;"Butler"<br>&nbsp;&nbsp;&nbsp;&nbsp;["name"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(8)&nbsp;"Reginald"<br>&nbsp;&nbsp;}<br>}</blockquote></div>   </div>  </div> </div></div>
 * 
     * Set the maximum number of documents to return.
     * @link https://www.php.net/manual/en/mysql-xdevapi-collectionfind.limit.php
     * @param int $rows
     * @return \mysql_xdevapi\CollectionFind
     */
    public function limit(int $rows): CollectionFind {}

    /**
 * <div id="mysql-xdevapi-collectionfind.lockexclusive" class="refentry"> <div class="refnamediv">  <h1 class="refname">CollectionFind::lockExclusive</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">CollectionFind::lockExclusive</span> — <span class="dc-title">Execute operation with EXCLUSIVE LOCK</span></p> </div> <div class="refsect1 description" id="refsect1-mysql-xdevapi-collectionfind.lockexclusive-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\CollectionFind::lockExclusive</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$lock_waiting_option</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mysql-xdevapi-collectionfind.php" class="type mysql_xdevapi\CollectionFind" style="color:#EAB766">mysql_xdevapi\CollectionFind</a></span></div>  <p class="para rdfs-comment">   Locks the document exclusively.   As long as the document is locked,   other transactions can't update the document,   use <span class="code">SELECT ... LOCK IN SHARE MODE</span>,   or read the data in certain transaction isolation levels.   Consistent reads ignore any locks set on the records that exist in the read view.  </p>  <p class="para">   To avoid concurrency problems, it makes sense to use this function with the   <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\Collection::modify()</strong></span> method. Essentially, this function uses row locks to serialise   access to rows.  </p> </div> <div class="refsect1 parameters" id="refsect1-mysql-xdevapi-collectionfind.lockexclusive-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">lock_waiting_option</span></dt>    <dd>     <p class="para">      Optional waiting option. By default it is <strong><span><a href="https://php.net/manual/zh/mysql-xdevapi.constants.php#constant.mysqlx-lock-default">MYSQLX_LOCK_DEFAULT</a></span></strong>. Valid values are these constants:     </p>     <ul class="itemizedlist">      <li class="listitem"><p class="para"><strong><span><a href="https://php.net/manual/zh/mysql-xdevapi.constants.php#constant.mysqlx-lock-default">MYSQLX_LOCK_DEFAULT</a></span></strong></p></li>      <li class="listitem"><p class="para"><strong><span><a href="https://php.net/manual/zh/mysql-xdevapi.constants.php#constant.mysqlx-lock-nowait">MYSQLX_LOCK_NOWAIT</a></span></strong></p></li>      <li class="listitem"><p class="para"><strong><span><a href="https://php.net/manual/zh/mysql-xdevapi.constants.php#constant.mysqlx-lock-skip-locked">MYSQLX_LOCK_SKIP_LOCKED</a></span></strong></p></li>     </ul>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mysql-xdevapi-collectionfind.lockexclusive-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   Returns a CollectionFind object that can be used for further processing.  </p> </div> <div class="refsect1 examples" id="refsect1-mysql-xdevapi-collectionfind.lockexclusive-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">mysql_xdevapi\CollectionFind::lockExclusive()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$session </span><span style="color: #007700">= </span><span style="color: #9876AA">mysql_xdevapi\getSession</span><span style="color: #007700">(</span><span style="color: #DD0000">"mysqlx://user:password@localhost"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$schema     </span><span style="color: #007700">= </span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getSchema</span><span style="color: #007700">(</span><span style="color: #DD0000">"addressbook"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$collection </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">startTransaction</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$collection<br>  </span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">find</span><span style="color: #007700">(</span><span style="color: #DD0000">"age &gt; 50"</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">lockExclusive</span><span style="color: #007700">()<br>  -&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #FF8000">// ... do an operation on the object<br><br>// Complete the transaction and unlock the document<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">commit</span><span style="color: #007700">();<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>  </div> </div></div>
 * 
     * Execute operation with EXCLUSIVE LOCK
     *
     * Lock exclusively the document, other transactions are blocked from updating the document until the document is locked While the document is locked, other transactions are blocked from updating those docs, from doing SELECT ... LOCK IN SHARE MODE, or from reading the data in certain transaction isolation levels. Consistent reads ignore any locks set on the records that exist in the read view.
     * This feature is directly useful with the modify() command, to avoid concurrency problems. Basically, it serializes access to a row through row locking
     *
     * @link https://www.php.net/manual/en/mysql-xdevapi-collectionfind.lockexclusive.php
     *
     * @param int $lock_waiting_option
     * @return \mysql_xdevapi\CollectionFind
     */
    public function lockExclusive(int $lock_waiting_option): CollectionFind {}

    /**
 * <div id="mysql-xdevapi-collectionfind.lockshared" class="refentry"> <div class="refnamediv">  <h1 class="refname">CollectionFind::lockShared</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">CollectionFind::lockShared</span> — <span class="dc-title">Execute operation with SHARED LOCK</span></p> </div> <div class="refsect1 description" id="refsect1-mysql-xdevapi-collectionfind.lockshared-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\CollectionFind::lockShared</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$lock_waiting_option</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mysql-xdevapi-collectionfind.php" class="type mysql_xdevapi\CollectionFind" style="color:#EAB766">mysql_xdevapi\CollectionFind</a></span></div>  <p class="para rdfs-comment">   Allows to share the documents between multiple transactions which are locking in shared mode.  </p>  <p class="para">   Other sessions can read the rows, but cannot modify them until your transaction commits.   </p>  <p class="para">   If any of these rows were changed by another transaction that hasn't been committed,   the query will wait until that transaction has ended to be able to use the latest values.  </p> </div> <div class="refsect1 parameters" id="refsect1-mysql-xdevapi-collectionfind.lockshared-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">lock_waiting_option</span></dt>    <dd>     <p class="para">      Optional waiting option. By default it is <strong><span><a href="https://php.net/manual/zh/mysql-xdevapi.constants.php#constant.mysqlx-lock-default">MYSQLX_LOCK_DEFAULT</a></span></strong>. Valid values are these constants:     </p>     <ul class="itemizedlist">      <li class="listitem"><p class="para"><strong><span><a href="https://php.net/manual/zh/mysql-xdevapi.constants.php#constant.mysqlx-lock-default">MYSQLX_LOCK_DEFAULT</a></span></strong></p></li>      <li class="listitem"><p class="para"><strong><span><a href="https://php.net/manual/zh/mysql-xdevapi.constants.php#constant.mysqlx-lock-nowait">MYSQLX_LOCK_NOWAIT</a></span></strong></p></li>      <li class="listitem"><p class="para"><strong><span><a href="https://php.net/manual/zh/mysql-xdevapi.constants.php#constant.mysqlx-lock-skip-locked">MYSQLX_LOCK_SKIP_LOCKED</a></span></strong></p></li>     </ul>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mysql-xdevapi-collectionfind.lockshared-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   A CollectionFind object that can be used for further processing  </p> </div> <div class="refsect1 examples" id="refsect1-mysql-xdevapi-collectionfind.lockshared-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">mysql_xdevapi\CollectionFind::lockShared()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$session </span><span style="color: #007700">= </span><span style="color: #9876AA">mysql_xdevapi\getSession</span><span style="color: #007700">(</span><span style="color: #DD0000">"mysqlx://user:password@localhost"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$schema     </span><span style="color: #007700">= </span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getSchema</span><span style="color: #007700">(</span><span style="color: #DD0000">"addressbook"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$collection </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">startTransaction</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$collection<br>  </span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">find</span><span style="color: #007700">(</span><span style="color: #DD0000">"age &gt; 50"</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">lockShared</span><span style="color: #007700">()<br>  -&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #FF8000">// ... read the object in shared mode<br><br>// Complete the transaction and unlock the document<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">commit</span><span style="color: #007700">();<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>  </div> </div></div>
 * 
     * Execute operation with SHARED LOCK
     *
     * Allows to share the documents between multiple transactions which are locking in shared mode.
     * Other sessions can read the rows, but cannot modify them until your transaction commits.
     * If any of these rows were changed by another transaction that has not yet committed,
     * your query waits until that transaction ends and then uses the latest values.
     *
     * @link https://www.php.net/manual/en/mysql-xdevapi-collectionfind.lockshared.php
     *
     * @param int $lock_waiting_option
     * @return \mysql_xdevapi\CollectionFind
     */
    public function lockShared(int $lock_waiting_option): CollectionFind {}

    /**
 * <div id="mysql-xdevapi-collectionfind.offset" class="refentry"> <div class="refnamediv">  <h1 class="refname">CollectionFind::offset</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">CollectionFind::offset</span> — <span class="dc-title">Skip given number of elements to be returned</span></p> </div> <div class="refsect1 description" id="refsect1-mysql-xdevapi-collectionfind.offset-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\CollectionFind::offset</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$position</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mysql-xdevapi-collectionfind.php" class="type mysql_xdevapi\CollectionFind" style="color:#EAB766">mysql_xdevapi\CollectionFind</a></span></div>  <p class="para rdfs-comment">   Skip (offset) these number of elements that otherwise would be returned   by the find operation. Use with the limit() method.  </p>  <p class="para">   Defining an offset larger than the result set size results in an empty set.  </p> </div> <div class="refsect1 parameters" id="refsect1-mysql-xdevapi-collectionfind.offset-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">position</span></dt>    <dd>     <p class="para">      Number of elements to skip for the limit() operation.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mysql-xdevapi-collectionfind.offset-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   A CollectionFind object that can be used for additional processing.  </p> </div> <div class="refsect1 examples" id="refsect1-mysql-xdevapi-collectionfind.offset-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">mysql_xdevapi\CollectionFind::offset()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$session </span><span style="color: #007700">= </span><span style="color: #9876AA">mysql_xdevapi\getSession</span><span style="color: #007700">(</span><span style="color: #DD0000">"mysqlx://user:password@localhost"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"DROP DATABASE IF EXISTS addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"CREATE DATABASE addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$schema </span><span style="color: #007700">= </span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getSchema</span><span style="color: #007700">(</span><span style="color: #DD0000">"addressbook"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$create </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$create<br>  </span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #DD0000">'{"name": "Alfred", "age": 18, "job": "Butler"}'</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$create<br>  </span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #DD0000">'{"name": "Reginald", "age": 42, "job": "Butler"}'</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #FF8000">// ...<br><br></span><span style="color: #9876AA">\$collection </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$collection<br>  </span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">find</span><span style="color: #007700">()<br>  -&gt;</span><span style="color: #9876AA">sort</span><span style="color: #007700">(</span><span style="color: #DD0000">'age asc'</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">offset</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">limit</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$result</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">fetchAll</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">array(1)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;array(4)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["_id"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(28)&nbsp;"00005b6b536100000000000000f3"<br>&nbsp;&nbsp;&nbsp;&nbsp;["age"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(42)<br>&nbsp;&nbsp;&nbsp;&nbsp;["job"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(6)&nbsp;"Butler"<br>&nbsp;&nbsp;&nbsp;&nbsp;["name"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(8)&nbsp;"Reginald"<br>&nbsp;&nbsp;}<br>}</blockquote></div>   </div>  </div> </div></div>
 * 
     * Skip given number of elements to be returned
     *
     * Skip (offset) these number of elements that otherwise would be returned by the find operation. Use with the limit() method.
     * Defining an offset larger than the result set size results in an empty set.
     *
     * @link https://www.php.net/manual/en/mysql-xdevapi-collectionfind.offset.php
     *
     * @param int $position
     * @return \mysql_xdevapi\CollectionFind
     */
    public function offset(int $position): CollectionFind {}

    /**
 * <div id="mysql-xdevapi-collectionfind.sort" class="refentry"> <div class="refnamediv">  <h1 class="refname">CollectionFind::sort</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">CollectionFind::sort</span> — <span class="dc-title">Set the sorting criteria</span></p> </div> <div class="refsect1 description" id="refsect1-mysql-xdevapi-collectionfind.sort-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\CollectionFind::sort</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$sort_expr</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mysql-xdevapi-collectionfind.php" class="type mysql_xdevapi\CollectionFind" style="color:#EAB766">mysql_xdevapi\CollectionFind</a></span></div>  <p class="para rdfs-comment">   Sort the result set by the field selected in the sort_expr argument. The allowed   orders are ASC (Ascending) or DESC (Descending). This operation is equivalent to the 'ORDER BY' SQL operation   and it follows the same set of rules.  </p> </div> <div class="refsect1 parameters" id="refsect1-mysql-xdevapi-collectionfind.sort-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">sort_expr</span></dt>    <dd>     <p class="para">      One or more sorting expressions can be provided. The evaluation is from left to right,      and each expression is separated by a comma.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mysql-xdevapi-collectionfind.sort-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   A CollectionFind object that can be used to execute the command, or to add additional operations.  </p> </div> <div class="refsect1 examples" id="refsect1-mysql-xdevapi-collectionfind.sort-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">mysql_xdevapi\CollectionFind::sort()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$session </span><span style="color: #007700">= </span><span style="color: #9876AA">mysql_xdevapi\getSession</span><span style="color: #007700">(</span><span style="color: #DD0000">"mysqlx://user:password@localhost"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"DROP DATABASE IF EXISTS addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"CREATE DATABASE addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$schema </span><span style="color: #007700">= </span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getSchema</span><span style="color: #007700">(</span><span style="color: #DD0000">"addressbook"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$create </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$create<br>  </span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #DD0000">'{"name": "Alfred", "age": 18, "job": "Butler"}'</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$create<br>  </span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #DD0000">'{"name": "Reginald", "age": 42, "job": "Butler"}'</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #FF8000">// ...<br><br></span><span style="color: #9876AA">\$collection </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$collection<br>  </span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">find</span><span style="color: #007700">()<br>  -&gt;</span><span style="color: #9876AA">sort</span><span style="color: #007700">(</span><span style="color: #DD0000">'job desc'</span><span style="color: #007700">, </span><span style="color: #DD0000">'age asc'</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$result</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">fetchAll</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">array(2)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;array(4)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["_id"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(28)&nbsp;"00005b6b53610000000000000106"<br>&nbsp;&nbsp;&nbsp;&nbsp;["age"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(18)<br>&nbsp;&nbsp;&nbsp;&nbsp;["job"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(6)&nbsp;"Butler"<br>&nbsp;&nbsp;&nbsp;&nbsp;["name"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(6)&nbsp;"Alfred"<br>&nbsp;&nbsp;}<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;array(4)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["_id"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(28)&nbsp;"00005b6b53610000000000000107"<br>&nbsp;&nbsp;&nbsp;&nbsp;["age"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(42)<br>&nbsp;&nbsp;&nbsp;&nbsp;["job"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(6)&nbsp;"Butler"<br>&nbsp;&nbsp;&nbsp;&nbsp;["name"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(8)&nbsp;"Reginald"<br>&nbsp;&nbsp;}<br>}</blockquote></div>   </div>  </div> </div></div>
 * 
     * Set the sorting criteria
     *
     * Sort the result set by the field selected in the sort_expr argument. The allowed orders are ASC (Ascending) or DESC (Descending). This operation is equivalent to the 'ORDER BY' SQL operation and it follows the same set of rules.
     *
     * @link https://www.php.net/manual/en/mysql-xdevapi-collectionfind.sort.php
     *
     * @param string $sort_expr
     * @return CollectionFind
     */
    public function sort(string $sort_expr): CollectionFind {}
}

