</dt>    <dd>     <p class="para">     The value to set on the specified attribute.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mysql-xdevapi-collectionmodify.replace-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   A CollectionModify object.  </p> </div> <div class="refsect1 examples" id="refsect1-mysql-xdevapi-collectionmodify.replace-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">mysql_xdevapi\CollectionModify::replace()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$session </span><span style="color: #007700">= </span><span style="color: #9876AA">mysql_xdevapi\getSession</span><span style="color: #007700">(</span><span style="color: #DD0000">"mysqlx://user:password@localhost"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"DROP DATABASE IF EXISTS addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"CREATE DATABASE addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$schema     </span><span style="color: #007700">= </span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getSchema</span><span style="color: #007700">(</span><span style="color: #DD0000">"addressbook"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$collection </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$collection<br>  </span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(<br>  </span><span style="color: #DD0000">'{"name":   "Bernie",<br>    "traits": ["Friend", "Brother", "Human"]}'</span><span style="color: #007700">) <br>  -&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$collection<br>  </span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">modify</span><span style="color: #007700">(</span><span style="color: #DD0000">"name = :name"</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">bind</span><span style="color: #007700">([</span><span style="color: #DD0000">'name' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'Bernie'</span><span style="color: #007700">])<br>  -&gt;</span><span style="color: #9876AA">replace</span><span style="color: #007700">(</span><span style="color: #DD0000">"name"</span><span style="color: #007700">, </span><span style="color: #DD0000">"Bern"</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span sty