 * <div id="mysql-xdevapi-collectionmodify.set" class="refentry"> <div class="refnamediv">  <h1 class="refname">CollectionModify::set</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">CollectionModify::set</span> — <span class="dc-title">Set document attribute</span></p> </div> <div class="refsect1 description" id="refsect1-mysql-xdevapi-collectionmodify.set-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\CollectionModify::set</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$collection_field</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$expression_or_literal</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mysql-xdevapi-collectionmodify.php" class="type mysql_xdevapi\CollectionModify" style="color:#EAB766">mysql_xdevapi\CollectionModify</a></span></div>  <p class="para rdfs-comment">   Sets or updates attributes on documents in a collection.  </p> </div> <div class="refsect1 parameters" id="refsect1-mysql-xdevapi-collectionmodify.set-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">collection_field</span></dt>    <dd>     <p class="para">     The document path (name) of the item to set.    </p>    </dd>          <dt><span class="parameter" style="color:#3A95FF">expression_or_literal</span></dt>    <dd>     <p class="para">      The value to set it to.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mysql-xdevapi-collectionmodify.set-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   A CollectionModify object.  </p> </div> <div class="refsect1 examples" id="refsect1-mysql-xdevapi-collectionmodify.set-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">mysql_xdevapi\CollectionModify::set()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$session </span><span style="color: #007700">= </span><span style="color: #9876AA">mysql_xdevapi\getSession</span><span style="color: #007700">(</span><span style="color: #DD0000">"mysqlx://user:password@localhost"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"DROP DATABASE IF EXISTS addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"CREATE DATABASE addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$schema     </span><span style="color: #007700">= </span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getSchema</span><span style="color: #007700">(</span><span style="color: #DD0000">"addressbook"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$collection </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$collection<br>  </span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(<br>  </span><span style="color: #DD0000">'{"name":   "Bernie",<br>    "traits": ["Friend", "Brother", "Human"]}'</span><span style="color: #007700">) <br>  -&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$collection<br>  </span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">modify</span><span style="color: #007700">(</span><span style="color: #DD0000">"name = :name"</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">bind</span><span style="color: #007700">([</span><span style="color: #DD0000">'name' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'Bernie'</span><span style="color: #007700">])<br>  -&gt;</span><span style="color: #9876AA">set</span><span style="color: #007700">(</span><span style="color: #DD0000">"name"</span><span style="color: #007700">, </span><span style="color: #DD0000">"Bern"</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$collection<br>  </span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">find</span><span style="color: #007700">()<br>  -&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$result</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">fetchAll</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Array<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;Array<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[_id]&nbsp;=&gt;&nbsp;00005b6b53610000000000000111<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[name]&nbsp;=&gt;&nbsp;Bern<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[traits]&nbsp;=&gt;&nbsp;Array<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;Friend<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;Brother<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;Human<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;)<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;)<br>)</blockquote></div>   </div>  </div> </div></div>
 * 
     * Sets or updates attributes on documents in a collection.
     * @link https://www.php.net/manual/en/mysql-xdevapi-collectionmodify.set.php
     * @param string $collection_field
     * @param string $expression_or_literal
     * @return \mysql_xdevapi\CollectionModify
     */
    public function set(string $collection_field, string $expression_or_literal): CollectionModify {}

    /**
 * <div id="mysql-xdevapi-collectionmodify.skip" class="refentry"> <div class="refnamediv">  <h1 class="refname">CollectionModify::skip</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">CollectionModify::skip</span> — <span class="dc-title">Skip elements</span></p> </div> <div class="refsect1 description" id="refsect1-mysql-xdevapi-collectionmodify.skip-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\CollectionModify::skip</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$position</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mysql-xdevapi-collectionmodify.php" class="type mysql_xdevapi\CollectionModify" style="color:#EAB766">mysql_xdevapi\CollectionModify</a></span></div>  <p class="para rdfs-comment">   Skips the first N elements that would otherwise be returned by a find operation.   If the number of elements skipped is larger than the size of the result set,   then the find operation returns an empty set.  </p> </div> <div class="refsect1 parameters" id="refsect1-mysql-xdevapi-collectionmodify.skip-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">position</span></dt>    <dd>     <p class="para">      Number of elements to skip.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mysql-xdevapi-collectionmodify.skip-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   A CollectionModify object to use for further processing.  </p> </div> <div class="refsect1 examples" id="refsect1-mysql-xdevapi-collectionmodify.skip-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">mysql_xdevapi\CollectionModify::skip()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$coll</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">modify</span><span style="color: #007700">(</span><span style="color: #DD0000">'age &gt; :age'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">sort</span><span style="color: #007700">(</span><span style="color: #DD0000">'age desc'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">unset</span><span style="color: #007700">([</span><span style="color: #DD0000">'age'</span><span style="color: #007700">])-&gt;</span><span style="color: #9876AA">bind</span><span style="color: #007700">([</span><span style="color: #DD0000">'age' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">20</span><span style="color: #007700">])-&gt;</span><span style="color: #9876AA">limit</span><span style="color: #007700">(</span><span style="color: #9876AA">4</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">skip</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>  </div> </div></div>
 * 
     * Skip the first N elements that would otherwise be returned by a find operation. If the number of elements skipped is larger than the size of the result set, then the find operation returns an empty set.
     * @link https://www.php.net/manual/en/mysql-xdevapi-collectionmodify.skip.php
     * @param int $position
     * @return \mysql_xdevapi\CollectionModify
     */
    public function skip(int $position): CollectionModify {}

    /**
 * <div id="mysql-xdevapi-collectionmodify.sort" class="refentry"> <div class="refnamediv">  <h1 class="refname">CollectionModify::sort</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">CollectionModify::sort</span> — <span class="dc-title">Set the sorting criteria</span></p> </div> <div class="refsect1 description" id="refsect1-mysql-xdevapi-collectionmodify.sort-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\CollectionModify::sort</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$sort_expr</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mysql-xdevapi-collectionmodify.php" class="type mysql_xdevapi\CollectionModify" style="color:#EAB766">mysql_xdevapi\CollectionModify</a></span></div>  <p class="para rdfs-comment">   Sorts the result set by the field selected in the sort_expr argument. The allowed   orders are ASC (Ascending) or DESC (Descending). This operation is equivalent to the 'ORDER BY' SQL operation   and it follows the same set of rules.  </p> </div> <div class="refsect1 parameters" id="refsect1-mysql-xdevapi-collectionmodify.sort-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">sort_expr</span></dt>    <dd>     <p class="para">      One or more sort expressions can be provided. The evaluation is from      left to right and each expression must be separated by a comma.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mysql-xdevapi-collectionmodify.sort-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   CollectionModify object that can be used for further processing.  </p> </div> <div class="refsect1 examples" id="refsect1-mysql-xdevapi-collectionmodify.sort-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">mysql_xdevapi\CollectionModify::sort()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$res </span><span style="color: #007700">= </span><span style="color: #9876AA">\$coll</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">modify</span><span style="color: #007700">(</span><span style="color: #DD0000">'true'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">sort</span><span style="color: #007700">(</span><span style="color: #DD0000">'name desc'</span><span style="color: #007700">, </span><span style="color: #DD0000">'age asc'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">limit</span><span style="color: #007700">(</span><span style="color: #9876AA">4</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">set</span><span style="color: #007700">(</span><span style="color: #DD0000">'Married'</span><span style="color: #007700">, </span><span style="color: #DD0000">'NO'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>  </div> </div></div>
 * 
     * Sort the result set by the field selected in the sort_expr argument. The allowed orders are ASC (Ascending) or DESC (Descending). This operation is equivalent to the 'ORDER BY' SQL operation and it follows the same set of rules.
     * @link https://www.php.net/manual/en/mysql-xdevapi-collectionmodify.sort.php
     * @param string $sort_expr
     * @return \mysql_xdevapi\CollectionModify
     */
    public function sort(string $sort_expr): CollectionModify {}

    /**
 * <div id="mysql-xdevapi-collectionmodify.unset" class="refentry"> <div class="refnamediv">  <h1 class="refname">CollectionModify::unset</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">CollectionModify::unset</span> — <span class="dc-title">Unset the value of document fields</span></p> </div> <div class="refsect1 description" id="refsect1-mysql-xdevapi-collectionmodify.unset-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\CollectionModify::unset</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> <span class="parameter" style="color:#3A95FF">\$fields</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mysql-xdevapi-collectionmodify.php" class="type mysql_xdevapi\CollectionModify" style="color:#EAB766">mysql_xdevapi\CollectionModify</a></span></div>  <p class="para rdfs-comment">   Removes attributes from documents in a collection.  </p> </div> <div class="refsect1 parameters" id="refsect1-mysql-xdevapi-collectionmodify.unset-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">fields</span></dt>    <dd>     <p class="para">      The attributes to remove from documents in a collection.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mysql-xdevapi-collectionmodify.unset-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   CollectionModify object that can be used for further processing.  </p> </div> <div class="refsect1 examples" id="refsect1-mysql-xdevapi-collectionmodify.unset-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">mysql_xdevapi\CollectionModify::unset()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$res </span><span style="color: #007700">= </span><span style="color: #9876AA">\$coll</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">modify</span><span style="color: #007700">(</span><span style="color: #DD0000">'job like :job_name'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">unset</span><span style="color: #007700">([</span><span style="color: #DD0000">"age"</span><span style="color: #007700">, </span><span style="color: #DD0000">"name"</span><span style="color: #007700">])-&gt;</span><span style="color: #9876AA">bind</span><span style="color: #007700">([</span><span style="color: #DD0000">'job_name' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'Plumber'</span><span style="color: #007700">])-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>  </div> </div></div>
 * 
     * Removes attributes from documents in a collection.
     * @link https://www.php.net/manual/en/mysql-xdevapi-collectionmodify.unset.php
     * @param array $fields
     * @return \mysql_xdevapi\CollectionModify
     */
    public function unset(array $fields): CollectionModify {}
}

