#9876AA">\$create</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #DD0000">'{"name": "Reginald", "age": 42, "job": "Butler"}'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #FF8000">// ...<br><br></span><span style="color: #9876AA">\$collection </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"people"</span><span style="color: #007700">);<br><br></span><span style="color: #FF8000">// Yields a DocResult object<br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$collection<br>  </span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">find</span><span style="color: #007700">(</span><span style="color: #DD0000">'job like :job and age &gt; :age'</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">bind</span><span style="color: #007700">([</span><span style="color: #DD0000">'job' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'Butler'</span><span style="color: #007700">, </span><span style="color: #DD0000">'age' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">16</span><span style="color: #007700">])<br>  -&gt;</span><span style="color: #9876AA">sort</span><span style="color: #007700">(</span><span style="color: #DD0000">'age desc'</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$result</span><s