ult</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getWarningsCount</span><span style="color: #007700">()) {<br>    echo </span><span style="color: #DD0000">"There was an error:\n"</span><span style="color: #007700">;<br>    </span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$result</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getWarnings</span><span style="color: #007700">());<br>    exit;<br>}<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$result</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">fetchOne</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">array(4)&nbsp;{<br>&nbsp;&nbsp;["_id"]=&gt;<br>&nbsp;&nbsp;string(28)&nbsp;"00005b6b53610000000000000135"<br>&nbsp;&nbsp;["age"]=&gt;<br>&nbsp;&nbsp;int(42)<br>&nbsp;&nbsp;["job"]=&gt;<br>&nbsp;&nbsp;string(6)&nbsp;"Butler"<br>&nbsp;&nbsp;["name"]=&gt;<br>&nbsp;&nbsp;string(8)&nbsp;"Reginald"<br>}</blockquote></div>   </div>  </div> </div></div>
