832"><strong>getGeneratedIds</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>getWarnings</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>getWarningsCount</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div>   }</div>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link Result::__construct} — Result constructor</li><li>{@link Result::getAffectedItemsCount} — Get affected row count</li><li>{@link Result::getAutoIncrementValue} — Get autoincremented value</li><li>{@link Result::getGeneratedIds} — Get generated ids</li><li>{@link Result::getWarnings} — Get warnings from last operation</li><li>{@link Result::getWarningsCount} — Get warning count from last operation</li></ul></div>
