><span style="color: #9876AA">mysql_xdevapi\getSession</span><span style="color: #007700">(</span><span style="color: #DD0000">"mysqlx://user:password@localhost"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"DROP DATABASE addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"CREATE DATABASE addressbook"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"CREATE TABLE addressbook.names(name text, age int)"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"INSERT INTO addressbook.names values ('John', 42), ('Sam', 33)"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$schema </span><span style="color: #007700">= </span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getSchema</span><span style="color: #007700">(</span><span style="color: #DD0000">"addressbook"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$table  </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getTable</span><span style="color: #007700">(</span><span style="color: #DD0000">"names"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$row </span><span style="color: #007700">= </span><span style="color: #9876AA">\$table</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">select</span><span style="color: #007700">(</span><span style="color: #DD0000">'name'</span><span style="color: #007700">, </span><span style="color: #DD0000">'age'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">()-&gt;</span><span style="color: #9876AA">fetchAll</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$row</span><span style="color: #007700">);</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Array<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;Array<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[name]&nbsp;=&gt;&nbsp;John<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[age]&nbsp;=&gt;&nbsp;42<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;)<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;Array<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[name]&nbsp;=&gt;&nbsp;Sam<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[age]&nbsp;=&gt;&nbsp;33<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;)<br>)</blockquote></div>   </div>  </div> </div></div>
 * 
