    /* Methods */
    /**
 * <div id="mysql-xdevapi-schema.createcollection" class="refentry"> <div class="refnamediv">  <h1 class="refname">Schema::createCollection</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">Schema::createCollection</span> — <span class="dc-title">Add collection to schema</span></p> </div> <div class="refsect1 description" id="refsect1-mysql-xdevapi-schema.createcollection-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\Schema::createCollection</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$name</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$validate</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mysql-xdevapi-collection.php" class="type mysql_xdevapi\Collection" style="color:#EAB766">mysql_xdevapi\Collection</a></span></div>  <p class="para rdfs-comment">   Create a collection within the schema.  </p> </div> <div class="refsect1 parameters" id="refsect1-mysql-xdevapi-schema.createcollection-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">name</span></dt>    <dd>     <p class="para">      Collection name.     </p>    </dd>          <dt><span class="parameter" style="color:#3A95FF">validate</span></dt>    <dd>     <p class="para">      Validation definition, as a JSON object.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mysql-xdevapi-schema.createcollection-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   The Collection object.  </p> </div> <div class="refsect1 changelog" id="refsect1-mysql-xdevapi-schema.createcollection-changelog">    <h3 class="title">更新日志</h3>    <table id="mysql-xdevapi-schema.createcollection.changelog" class="doctable informaltable">           <thead>       <tr>        <th>版本</th>        <th>说明</th>       </tr>      </thead>      <tbody class="tbody">       <tr>        <td>8.0.20</td>        <td>         Added the optional validate parameter.        </td>       </tr>      </tbody>         </table> </div> <div class="refsect1 examples" id="refsect1-mysql-xdevapi-schema.createcollection-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\Schema::createCollection()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$session </span><span style="color: #007700">= </span><span style="color: #9876AA">mysql_xdevapi\getSession</span><span style="color: #007700">(</span><span style="color: #DD0000">"mysqlx://user:password@localhost"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"DROP DATABASE IF EXISTS food"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"CREATE DATABASE food"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">sql</span><span style="color: #007700">(</span><span style="color: #DD0000">"CREATE TABLE food.fruit(name text, rating text)"</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$schema </span><span style="color: #007700">= </span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getSchema</span><span style="color: #007700">(</span><span style="color: #DD0000">"food"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"trees"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">gettables</span><span style="color: #007700">());<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getcollections</span><span style="color: #007700">());</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Array<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[fruit]&nbsp;=&gt;&nbsp;mysql_xdevapi\Table&nbsp;Object<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[name]&nbsp;=&gt;&nbsp;fruit<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;)<br>)<br>Array<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[trees]&nbsp;=&gt;&nbsp;mysql_xdevapi\Collection&nbsp;Object<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[name]&nbsp;=&gt;&nbsp;trees<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;)<br>)</blockquote></div>   </div>  </div>  <div class="example" id="example-2">    <p><strong>示例 #2 <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\Schema::createCollection()</strong></span> example</strong></p>    <div class="example-contents"> <div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br> \$collection </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">createCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"mycollection"</span><span style="color: #007700">, </span><span style="color: #DD0000">'{<br>    "validation": {<br>        "level": "strict",<br>        "schema": {<br>            "id": "http://json-schema.org/geo",<br>            "description": "A geographical coordinate",<br>            "type": "object",<br>            "properties": {<br>                "latitude": {<br>                    "type": "number"<br>                },<br>                "longitude": {<br>                    "type": "number"<br>                }<br>            },<br>            "required": ["latitude", "longitude"]<br>        }<br>    }<br>}'</span><span style="color: #007700">);<br></span><span style="color: #FF8000">// Succeeds<br></span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #DD0000">'{"latitude": 10, "longitude": 20}'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #FF8000">// Fails, invalid types (not numbers)<br></span><span style="color: #9876AA">\$collection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">add</span><span style="color: #007700">(</span><span style="color: #DD0000">'{"latitude": "lat", "longitude": "long"}'</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();</span></span></blockquote></div>    </div>   </div> </div></div>
 * 
