    /**
 * <div id="mysql-xdevapi-tableselect.lockexclusive" class="refentry"> <div class="refnamediv">  <h1 class="refname">TableSelect::lockExclusive</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">TableSelect::lockExclusive</span> — <span class="dc-title">Execute EXCLUSIVE LOCK</span></p> </div> <div class="refsect1 description" id="refsect1-mysql-xdevapi-tableselect.lockexclusive-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>mysql_xdevapi\TableSelect::lockExclusive</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$lock_waiting_option</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mysql-xdevapi-tableselect.php" class="type mysql_xdevapi\TableSelect" style="color:#EAB766">mysql_xdevapi\TableSelect</a></span></div>  <p class="para rdfs-comment">   Execute a read operation with EXCLUSIVE LOCK. Only one lock can be active at a time.  </p> </div> <div class="refsect1 parameters" id="refsect1-mysql-xdevapi-tableselect.lockexclusive-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">lock_waiting_option</span></dt>    <dd>     <p class="para">      The optional waiting option that defaults to <strong><span><a href="https://php.net/manual/zh/mysql-xdevapi.constants.php#constant.mysqlx-lock-default">MYSQLX_LOCK_DEFAULT</a></span></strong>.      Valid values are:     </p>     <ul class="itemizedlist">      <li class="listitem"><p class="para"><strong><span><a href="https://php.net/manual/zh/mysql-xdevapi.constants.php#constant.mysqlx-lock-default">MYSQLX_LOCK_DEFAULT</a></span></strong></p></li>      <li class="listitem"><p class="para"><strong><span><a href="https://php.net/manual/zh/mysql-xdevapi.constants.php#constant.mysqlx-lock-nowait">MYSQLX_LOCK_NOWAIT</a></span></strong></p></li>      <li class="listitem"><p class="para"><strong><span><a href="https://php.net/manual/zh/mysql-xdevapi.constants.php#constant.mysqlx-lock-skip-locked">MYSQLX_LOCK_SKIP_LOCKED</a></span></strong></p></li>     </ul>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mysql-xdevapi-tableselect.lockexclusive-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   TableSelect object.  </p> </div> <div class="refsect1 examples" id="refsect1-mysql-xdevapi-tableselect.lockexclusive-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">mysql_xdevapi\TableSelect::lockExclusive()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$session </span><span style="color: #007700">= </span><span style="color: #9876AA">mysql_xdevapi\getSession</span><span style="color: #007700">(</span><span style="color: #DD0000">"mysqlx://user:password@localhost"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$schema </span><span style="color: #007700">= </span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getSchema</span><span style="color: #007700">(</span><span style="color: #DD0000">"addressbook"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$table  </span><span style="color: #007700">= </span><span style="color: #9876AA">\$schema</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getTable</span><span style="color: #007700">(</span><span style="color: #DD0000">"names"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">startTransaction</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$table</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">select</span><span style="color: #007700">(</span><span style="color: #DD0000">'name'</span><span style="color: #007700">, </span><span style="color: #DD0000">'age'</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">lockExclusive</span><span style="color: #007700">(</span><span style="color: #9876AA">MYSQLX_LOCK_NOWAIT</span><span style="color: #007700">)<br>  -&gt;</span><span style="color: #9876AA">execute</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$session</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">commit</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">\$row </span><span style="color: #007700">= </span><span style="color: #9876AA">\$result</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">fetchAll</span><span style="color: #007700">();<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$row</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Array<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;Array<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[name]&nbsp;=&gt;&nbsp;John<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[age]&nbsp;=&gt;&nbsp;42<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;)<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;Array<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[name]&nbsp;=&gt;&nbsp;Sam<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[age]&nbsp;=&gt;&nbsp;42<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;)<br>)</blockquote></div>   </div>  </div> </div></div>
